-- DIBUAT OTOMATIS oleh tools/gen-seed.mjs dari src/data.js. Jangan edit manual; ubah data.js lalu jalankan ulang.

on conflict (id) do update set name = excluded.name, data_as_of = excluded.data_as_of, tickets = excluded.tickets;

on conflict (destination_id, id) do update set name = excluded.name, short_name = excluded.short_name, cat = excluded.cat, icon = excluded.icon, price = excluded.price, status = excluded.status, dwell = excluded.dwell, tags = excluded.tags, description = excluded.description, tips = excluded.tips, pos = excluded.pos, verified = excluded.verified, plan = excluded.plan, updated_at = now();

on conflict (destination_id, id) do update set name = excluded.name, type = excluded.type, pos = excluded.pos, verified = excluded.verified, updated_at = now();

on conflict (destination_id, id) do update set name = excluded.name, name_en = excluded.name_en, latin = excluded.latin, iucn = excluded.iucn, zone_id = excluded.zone_id, fact = excluded.fact, updated_at = now();

on conflict (destination_id, id) do update set name = excluded.name, hint = excluded.hint, pos = excluded.pos;

-- jadwal awal hanya diisi bila destinasi belum punya jadwal (supaya hasil edit pengelola tidak hilang)
select v.* from (values
('kbs', time '09:30', 20, 'Feeding jerapah', 'sabana', 'Jadwal 2017, menunggu pembaruan pengelola'),
('kbs', time '09:45', 45, 'Pawai Satwa', 'plaza', 'Hanya pada hari event'),
('kbs', time '10:00', 20, 'Talk With Us: keeper komodo', 'komodo', 'Setiap hari selama musim libur'),
('kbs', time '11:00', 20, 'Feeding arapaima', 'aquanoctudio', 'Jadwal 2017, menunggu pembaruan pengelola'),
('kbs', time '12:00', 20, 'Feeding buaya', 'reptil', 'Jadwal 2017, menunggu pembaruan pengelola'),
('kbs', time '13:00', 45, 'Animal Edutainment', 'jamur', 'Sabtu, Minggu, dan libur nasional'),
('kbs', time '14:00', 30, 'Feeding gajah', 'gajah', 'Pengganti tunggang gajah sejak Nov 2025'),
('kbs', time '15:00', 45, 'Bekantan aktif di pulau', 'perahu', 'Pengamatan pengunjung, bukan jadwal resmi')
) as v(destination_id, t, dur, title, zone_id, note)
where not exists (select 1 from public.schedules where destination_id = 'kbs');
