insert into public.destinations (id, name, plan, max_points, data_as_of, tickets) values ('kbs', 'Kebun Binatang Surabaya', 'standard', 100, 'Okt 2026', '{"entry":[{"label":"Tiket masuk","price":"Rp15.000","note":"Flat setiap hari, termasuk akhir pekan & libur"},{"label":"Anak tinggi < 85 cm","price":"Gratis","note":""},{"label":"Rombongan sekolah (≥30 orang)","price":"Rp13.000","note":"Hari kerja, +1 tiket gratis"}],"bundles":[{"code":"A","price":"Rp65.000","items":"Masuk · Kids Zoo · Aquanoctudio · Animal Edutainment"},{"code":"B","price":"Rp45.000","items":"Masuk · Kids Zoo · Aquanoctudio"},{"code":"C","price":"Rp35.000","items":"Masuk · Kids Zoo · GIZ Park"},{"code":"D","price":"Rp30.000","items":"Masuk · Kids Zoo · Animal Story"},{"code":"E","price":"Rp20.000","items":"Masuk · Kids Zoo"}],"rides":[{"label":"Aquanoctudio","price":"Rp30.000"},{"label":"Tunggang unta","price":"Rp35.000"},{"label":"Perahu Pulau Bekantan","price":"Rp15.000–20.000"},{"label":"Animal Story","price":"Rp15.000"},{"label":"GIZ Park","price":"Rp15.000"},{"label":"Perosotan Rainbow","price":"Rp20.000"},{"label":"Feeding satwa","price":"Rp25.000–100.000"},{"label":"Foto bersama satwa","price":"Rp25.000"}],"parking":[{"label":"Motor (dalam KBS)","price":"Rp5.000"},{"label":"Mobil (dalam KBS)","price":"Rp10.000"},{"label":"Mobil di TIJ","price":"Rp6.000 / 2 jam pertama"}],"asOf":"Harga per Nov 2025 (paket & wahana) dan Apr 2026 (tiket & parkir). Konfirmasi di loket."}'::jsonb)
insert into public.zones (destination_id, id, name, short_name, cat, icon, price, status, dwell, tags, description, tips, pos, verified, plan) values
('kbs', 'gerbang', 'Pintu Utama & Plaza Sura-Baya', 'Pintu Utama', 'layanan', 'gate', 'Rp15.000', 'buka', 5, array['foto']::text[], 'Gerbang utama dengan patung ikonik Sura (hiu) dan Baya (buaya), asal-usul nama Surabaya. Loket hanya menerima pembayaran non-tunai: QRIS dan Brizzi.', 'Plaza depan sedang ditata ulang (2026). Pintu masuk dan keluar akan disatukan, jadi ikuti papan arah terbaru.', array[23.5,-7.5]::double precision[], true, '{}'::jsonb),
('kbs', 'selatan', 'Pintu Selatan · Tunnel Joyoboyo', 'Pintu Selatan', 'layanan', 'gate', 'Rp15.000', 'buka', 3, '{}'::text[], 'Terhubung ke Terminal Intermoda Joyoboyo (TIJ) lewat terowongan pejalan kaki ±160 m berhias video mapping satwa, dibuka Desember 2024. Ada 4 loket.', 'Paling praktis bila datang naik Suroboyo Bus atau parkir mobil di TIJ.', array[46,32]::double precision[], true, '{}'::jsonb),
('kbs', 'pos12', 'Pos 12 · Parkir Dalam', 'Parkir · Pos 12', 'layanan', 'parking', 'Motor Rp5.000 · Mobil Rp10.000', 'buka', 2, '{}'::text[], 'Pintu samping dekat area parkir dalam. Parkir di KBS sudah non-tunai (QRIS & e-money) sejak April 2026.', 'Saat libur panjang, mobil diarahkan parkir di TIJ dan motor di dalam KBS.', array[45,4]::double precision[], true, '{}'::jsonb),
('kbs', 'aviary', 'Aviary Raksasa', 'Aviary', 'satwa', 'bird', 'Gratis', 'cek', 15, array['burung','foto','anak']::text[], 'Kandang burung walk-through berukuran sangat besar. Pengunjung berjalan di dalam kubah bersama burung air dan burung pantai.', 'Status operasional 2026 belum terkonfirmasi (sempat ditutup Agustus 2024). Cek info pengelola sebelum ke sini.', array[-8,-30]::double precision[], true, '{"grp":["burung"],"act":"satwa","kids":1,"effort":1}'::jsonb),
('kbs', 'aves', 'Rumah Burung (Aves)', 'Rumah Burung', 'satwa', 'bird', 'Gratis', 'buka', 15, array['burung','langka','edukasi']::text[], 'Deretan aviary berisi jalak bali, lima spesies rangkong, kasuari, kakatua jambul kuning, flamingo, dan kroonkraan.', 'KBS menangkarkan jalak bali sejak 1987 dan melepasliarkan 40 ekor ke TN Bali Barat pada 2011.', array[20,17]::double precision[], true, '{"grp":["burung"],"act":"satwa","kids":1,"effort":0,"indoor":true}'::jsonb),
('kbs', 'menara', 'Menara Pandang', 'Menara', 'wahana', 'tower', 'Gratis', 'cek', 5, array['foto','sejarah']::text[], 'Menara peninggalan era Hindia Belanda di samping Pulau Bekantan. Dulu dipakai melihat panorama kebun binatang dan kota, kini dipertahankan sebagai situs sejarah.', 'Akses naik ke menara belum terkonfirmasi. Spot foto terbaik dari tepi danau.', array[-6,-19]::double precision[], true, '{"act":"foto","kids":1,"effort":2,"access":false}'::jsonb),
('kbs', 'perahu', 'Wisata Perahu & Pulau Bekantan', 'Perahu & Bekantan', 'wahana', 'boat', 'Rp15.000 (hari kerja) · Rp20.000 (akhir pekan)', 'buka', 20, array['anak','langka','foto','air']::text[], 'Perahu mengelilingi Pulau Bekantan. Di pulau itu bekantan hidup bersama rusa Bawean, satwa endemik Jawa Timur yang kritis.', 'Bekantan sering terlihat aktif keluar pulau sekitar pukul 15.00. Harga perahu dari data 2023–2024, konfirmasi di dermaga.', array[-17,-13]::double precision[], true, '{"grp":["primata"],"act":"wahana","kids":2,"effort":1,"access":false}'::jsonb),
('kbs', 'aoudad', 'Pulau Siamang & Gunung Aoudad', 'Pulau Siamang', 'satwa', 'paw', 'Gratis', 'buka', 10, array['primata','air']::text[], 'Pulau siamang dan ''gunung'' batu domba Barbary (aoudad) yang dikelilingi parit. Perahu kayuh berkeliling di sekitarnya.', 'Dengarkan ''nyanyian'' siamang pada pagi hari, suaranya terdengar hingga jauh.', array[-13,3]::double precision[], false, '{"grp":["primata","savana"],"act":"satwa","kids":1,"effort":0}'::jsonb),
('kbs', 'panggung', 'Panggung Anak · Animal Story', 'Animal Story', 'wahana', 'film', 'Rp15.000 · Paket D', 'buka', 20, array['anak','edukasi']::text[], 'Gedung Panggung Anak kini menjadi lokasi Animal Story, film animasi 3D/digital tentang evolusi satwa sejak era dinosaurus.', 'Paket D (Rp30.000) sudah termasuk tiket masuk, Kids Zoo, dan Animal Story.', array[2,-27]::double precision[], true, '{"act":"show","kids":2,"effort":0,"ages":["balita","anak"]}'::jsonb),
('kbs', 'unta', 'Tunggang Unta', 'Tunggang Unta', 'wahana', 'ride', 'Rp35.000/anak', 'buka', 10, array['anak']::text[], 'Berkeliling singkat menunggang unta punuk satu (dromedari) dengan pendamping keeper.', 'Info 2024: tidak tersedia Senin dan Jumat. Konfirmasi jadwal di lokasi.', array[7,-17]::double precision[], true, '{"grp":["interaksi"],"act":"wahana","kids":2,"effort":0,"ride":{"min":3,"max":12,"note":"Tunggang unta"}}'::jsonb),
('kbs', 'komodo', 'Kompleks Komodo', 'Komodo', 'satwa', 'paw', 'Gratis', 'buka', 15, array['langka','reptil','edukasi','foto']::text[], 'Delapan kandang komodo dalam satu kompleks. KBS pernah memelihara 134 komodo (2022), populasi ex-situ terbesar di dunia, dan pada 2026 meminjamkan sepasang ke iZoo, Jepang.', 'Ikuti sesi keeper ''Talk With Us'' pukul 10.00 saat musim libur.', array[8,-6]::double precision[], true, '{"grp":["reptil"],"act":"satwa","kids":1,"effort":0}'::jsonb),
('kbs', 'reptil', 'Rumah Reptil & Kolam Buaya', 'Reptil & Buaya', 'satwa', 'paw', 'Gratis', 'buka', 15, array['reptil','edukasi']::text[], 'Deretan kandang iguana, kobra jawa, sanca kembang, sanca bodo, dan soa-soa, plus kolam buaya muara dan senyulong.', 'Jadwal feeding buaya diumumkan pengelola. Pantau tab Jadwal.', array[6,23]::double precision[], true, '{"grp":["reptil"],"act":"satwa","kids":1,"effort":0,"indoor":true}'::jsonb),
('kbs', 'kucing', 'Kucing Besar', 'Kucing Besar', 'satwa', 'paw', 'Gratis', 'buka', 15, array['kucing','langka','foto']::text[], 'Singa Afrika, harimau Sumatra, harimau Benggala, dan harimau putih. Anak singa Bima dan Dona (lahir April 2023) adalah kelahiran singa pertama KBS dalam 18 tahun.', 'Kucing besar lebih aktif pagi hari sebelum udara panas.', array[-29,-1]::double precision[], false, '{"grp":["kucing"],"act":"satwa","kids":1,"effort":0}'::jsonb),
('kbs', 'primata', 'Dunia Primata', 'Primata', 'satwa', 'paw', 'Gratis', 'buka', 15, array['primata','langka','anak']::text[], 'Orangutan Kalimantan, lutung jawa, makaka Jepang, baboon hamadryas, dan lemur ekor cincin di bagian belakang kebun binatang.', 'Jangan memberi makanan sendiri. Gunakan program feeding resmi.', array[-41,13]::double precision[], false, '{"grp":["primata"],"act":"satwa","kids":2,"effort":0}'::jsonb),
('kbs', 'gajah', 'Area Gajah', 'Gajah', 'satwa', 'paw', 'Feeding gajah (cek loket)', 'buka', 15, array['langka','anak','foto']::text[], 'Gajah Sumatra, di antaranya Gonzales (lahir 2010) dan bayi Rocky (dikenalkan 2024). Tunggang gajah dihentikan November 2025 demi kesejahteraan satwa, diganti sesi feeding gajah.', 'Bekas area tunggang gajah kini menjadi Go-Kart (dibuka Desember 2025).', array[-29,15]::double precision[], true, '{"grp":["savana","interaksi"],"act":"satwa","kids":2,"effort":0}'::jsonb),
('kbs', 'gokart', 'Go-Kart', 'Go-Kart', 'wahana', 'ride', 'Cek di loket', 'buka', 15, array['anak','wahana']::text[], 'Lintasan go-kart di bekas area tunggang gajah, dibuka 24 Desember 2025.', 'Harga belum dipublikasikan resmi.', array[-41,27]::double precision[], true, '{"act":"wahana","kids":2,"effort":0,"ride":{"min":6,"max":15,"note":"Go-kart"}}'::jsonb),
('kbs', 'sabana', 'Sabana Afrika', 'Sabana Afrika', 'satwa', 'paw', 'Gratis · Feeding jerapah Rp100.000/paket', 'buka', 15, array['anak','foto','langka']::text[], 'Padang terbuka untuk jerapah, zebra, sitatunga, dan burung unta. Sepasang jerapah dari Jepang dijadwalkan menyusul.', 'Feeding jerapah dari panggung pandang adalah momen favorit anak-anak.', array[-10,17]::double precision[], false, '{"grp":["savana","interaksi"],"act":"satwa","kids":2,"effort":0}'::jsonb),
('kbs', 'kudanil', 'Kuda Nil & Babirusa', 'Kuda Nil', 'satwa', 'paw', 'Gratis', 'buka', 10, array['langka','air']::text[], 'Satu kandang kuda nil dan tiga kandang kuda nil kerdil berjajar, bersebelahan dengan babirusa Sulawesi, salah satu maskot KBS.', 'Kuda nil paling sering muncul ke permukaan saat diberi makan.', array[-26,29]::double precision[], false, '{"grp":["savana","air"],"act":"satwa","kids":1,"effort":0}'::jsonb),
('kbs', 'herbivora', 'Padang Rusa & Banteng', 'Rusa & Banteng', 'satwa', 'paw', 'Feeding rusa ±Rp20.000–25.000', 'buka', 10, array['anak','langka']::text[], 'Satwa berkuku asli Indonesia: banteng Jawa, anoa, rusa timor, sambar, dan kijang. Ada spot feeding rusa di samping Jembatan Cinta.', 'Beli pakan resmi di lokasi. Pakan dari luar bisa membuat satwa sakit.', array[-1,-7]::double precision[], false, '{"grp":["savana","interaksi"],"act":"satwa","kids":1,"effort":1}'::jsonb),
('kbs', 'beruang', 'Beruang Madu & Binturong', 'Beruang Madu', 'satwa', 'paw', 'Gratis', 'buka', 10, array['langka']::text[], 'Beruang madu, beruang terkecil di dunia, dan binturong yang tubuhnya beraroma mirip popcorn.', 'Binturong aktif menjelang sore.', array[-17,30]::double precision[], false, '{"grp":["savana"],"act":"satwa","kids":1,"effort":0}'::jsonb),
('kbs', 'konservasi', 'Pusat Konservasi', 'Konservasi', 'staf', 'leaf', 'Area non-publik', 'buka', 0, '{}'::text[], 'Area penangkaran, termasuk jalak bali. Tidak dibuka untuk umum.', '', array[-8,33]::double precision[], false, '{}'::jsonb),
('kbs', 'nursery', 'Nursery', 'Nursery', 'staf', 'leaf', 'Area non-publik', 'buka', 0, '{}'::text[], 'Ruang inkubator dan nursery box untuk penetasan telur komodo, dengan masa inkubasi 7–8 bulan.', '', array[-35,35]::double precision[], true, '{}'::jsonb),
('kbs', 'karantina', 'Karantina', 'Karantina', 'staf', 'lock', 'Area non-publik', 'buka', 0, '{}'::text[], 'Satwa baru, misalnya kura-kura raksasa Aldabra yang tiba Juli 2026, dikarantina di sini sebelum dipamerkan.', '', array[-44,33]::double precision[], true, '{}'::jsonb),
('kbs', 'masjid', 'Masjid', 'Masjid', 'layanan', 'mosque', 'Gratis', 'buka', 15, '{}'::text[], 'Masjid di dalam kawasan KBS untuk salat berjamaah, lengkap dengan tempat wudu.', '', array[0,33]::double precision[], true, '{}'::jsonb),
('kbs', 'aquanoctudio', 'Aquanoctudio', 'Aquanoctudio', 'satwa', 'fish', 'Rp30.000 · Paket A/B', 'buka', 30, array['anak','edukasi','air','langka']::text[], 'Aquarium, Nocturama, dan Diorama dalam satu gedung (diresmikan Mei 2022). Ada sayap air laut dan air tawar, kolam arapaima, penyu hijau, serta rumah satwa malam.', 'Tiket dibeli di loket tersendiri. Ruangan sejuk, cocok saat siang terik.', array[17,30]::double precision[], true, '{"grp":["air"],"act":"satwa","kids":2,"effort":0,"indoor":true}'::jsonb),
('kbs', 'direksi', 'Kantor Direksi', 'Direksi', 'staf', 'building', 'Area non-publik', 'buka', 0, '{}'::text[], 'Kantor manajemen Perumda KBS.', '', array[30,31]::double precision[], true, '{}'::jsonb),
('kbs', 'sekretariat', 'Sekretariat', 'Sekretariat', 'staf', 'building', 'Area non-publik', 'buka', 0, '{}'::text[], 'Sekretariat dan administrasi KBS, termasuk layanan rombongan sekolah.', '', array[40,-6]::double precision[], true, '{}'::jsonb),
('kbs', 'kidszoo', 'Kids Zoo', 'Kids Zoo', 'wahana', 'paw', 'Rp10.000 · Paket E Rp20.000', 'buka', 20, array['anak','edukasi']::text[], 'Kebun satwa jinak: kelinci, domba, kambing, ayam, dan kolam koi yang ikannya boleh disentuh.', 'Paket feeding Kids Zoo Rp35.000. Cuci tangan setelah menyentuh satwa.', array[41,22]::double precision[], true, '{"grp":["interaksi"],"act":"wahana","kids":2,"effort":0,"ages":["balita","anak"]}'::jsonb),
('kbs', 'jamur', 'Rumah Jamur & Playland', 'Rumah Jamur', 'wahana', 'ride', 'Outbound Rp15.000', 'buka', 20, array['anak','foto','wahana']::text[], 'Rumah-rumah jamur raksasa dengan outbound (jembatan gantung, wall climbing), kafe, dan panggung utama di depannya.', 'Panggung utama di depan Rumah Jamur dipakai untuk Animal Edutainment akhir pekan.', array[15,10]::double precision[], true, '{"act":"wahana","kids":2,"effort":1,"ride":{"min":3,"max":12,"note":"Playland & outbound"}}'::jsonb),
('kbs', 'rainbow', 'Rainbow Park', 'Rainbow Park', 'wahana', 'ride', 'Perosotan Rp20.000 (3x) · Paket Rp30.000', 'buka', 20, array['anak','foto','wahana']::text[], 'Perosotan pelangi, playground, panjat dinding, dan Bioskop 7D (dibuka 2025).', '', array[25,9]::double precision[], true, '{"act":"wahana","kids":2,"effort":1,"ride":{"min":3,"note":"Perosotan Rainbow"}}'::jsonb),
('kbs', 'giz', 'GIZ Park', 'GIZ Park', 'wahana', 'sparkle', 'Rp15.000 · Paket C', 'buka', 15, array['anak','wahana','edukasi']::text[], 'Glow Interactive Zoo: hologram dan video mapping satwa tanpa satwa hidup, dibuka akhir Desember 2024.', '', array[31,0]::double precision[], true, '{"act":"wahana","kids":2,"effort":0,"ride":{"min":3,"max":15,"note":"GIZ Park"}}'::jsonb),
('kbs', 'plaza', 'Plaza Tengah', 'Plaza Tengah', 'layanan', 'users', 'Gratis', 'buka', 5, array['foto']::text[], 'Titik kumpul Pawai Satwa pada hari-hari event (09.45–10.30) dan tempat istirahat di tengah kebun binatang.', '', array[6,4]::double precision[], true, '{}'::jsonb),
