insert into public.animals (destination_id, id, name, name_en, latin, iucn, zone_id, fact) values
('kbs', 'komodo', 'Komodo', 'Komodo dragon', 'Varanus komodoensis', 'EN', 'komodo', 'Kadal terbesar di dunia. Air liurnya mengandung protein bisa yang mencegah darah membeku.'),
('kbs', 'bekantan', 'Bekantan', 'Proboscis monkey', 'Nasalis larvatus', 'EN', 'perahu', 'Hidung besar bekantan jantan berfungsi memperkeras suara panggilannya.'),
('kbs', 'rusabawean', 'Rusa Bawean', 'Bawean deer', 'Axis kuhlii', 'CR', 'perahu', 'Di alam hanya hidup di Pulau Bawean, Jawa Timur.'),
('kbs', 'jalakbali', 'Jalak Bali', 'Bali myna', 'Leucopsar rothschildi', 'CR', 'aves', 'Endemik Bali. KBS melepasliarkan 40 ekor ke Taman Nasional Bali Barat pada 2011.'),
('kbs', 'rangkong', 'Rangkong / Julang Emas', 'Wreathed hornbill', 'Rhyticeros undulatus', 'VU', 'aves', 'Disebut ''petani hutan'' karena menyebarkan biji buah ke penjuru hutan.'),
